{"drafts": [{"draft_id": "28b4e106-7b72-5859-9f85-541e4932f48b", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "name": "容量折减事故处理", "description": "当边存在激活事故且给出 CapacityMultiplier 时，按折减系数计算该边的有效容量，并据此更新排队与通行状态。用于事故激活期间的容量计算。", "asset_type": "micro_skill", "granularity": "micro", "asset_node_id": "micro_skill_node", "asset_path": "family_root/macro_skill/workflow_skill/micro_skill_node", "asset_level": 3, "visible_role": "leaf", "objective": "按事故容量乘数计算受影响边的有效容量", "domain": "交通仿真", "task_family": "容量与排队计算", "method_family": "容量乘数折减", "stage": "事故影响更新", "applicable_signals": ["边存在激活事故且给出 CapacityMultiplier", "需更新受影响边容量与队列"], "contraindications": ["无事故激活", "事故未指定容量乘数"], "intervention_moves": ["读取受影响边上的激活事故及其 CapacityMultiplier", "将原容量乘以 CapacityMultiplier 得到有效容量", "以有效容量更新该边的排队与通行状态"], "workflow_steps": ["确认受影响边上存在激活事故且已给出 CapacityMultiplier", "计算有效容量 = 原容量 × CapacityMultiplier", "以有效容量更新该边的排队与通行状态", "输出折减后的有效容量及更新后的队列状态"], "triggers": ["边存在激活事故且给出 CapacityMultiplier", "需更新受影响边容量与队列"], "constraints": ["仅在事故激活且指定容量乘数时执行", "有效容量必须基于原容量与乘数计算，不得凭空设定"], "cautions": ["事故未指定容量乘数时不应套用折减"], "output_contract": ["输出折减后的有效容量及更新后的队列状态"], "examples": [{"input": "E9（N4 至 N9）上存在事故 I1，CapacityMultiplier = 0.5", "output": "E9 有效容量 = 原容量 × 0.5，并据此更新 E9 的排队与通行状态", "notes": ""}], "risk_class": "low", "confidence": 0.65, "support_ids": ["2774c35e-1852-5ec3-b78f-6d0bcf5196ef"], "metadata": {"prompt": "识别受影响边上的激活事故及其 CapacityMultiplier，将原容量乘以该乘数得到有效容量，再以有效容量更新该边的排队与通行状态，最后输出折减后的有效容量及更新后的队列状态。", "tags": ["交通仿真", "容量折减", "事故处理", "排队计算"], "files": {}, "resources": {}, "source_sections": ["User Questions"], "extraction_unit": "window", "domain_type": "traffic simulation rules", "taxonomy_id": "traffic simulation rules", "asset_node_id": "micro_skill_node", "asset_path": "family_root/macro_skill/workflow_skill/micro_skill_node", "asset_level": 3, "visible_role": "leaf", "candidate_slot": 2, "window_id": "0d40d51a-a72b-555d-998b-30fe932e7857", "window_strategy": "strict", "anchor_hits": [], "paragraph_start": 7, "paragraph_end": 9, "heading_path": ["User Questions"], "parent_heading": "", "sibling_headings": ["CL-Bench: Empirical Discovery & Simulation / Simulation Environment", "System Context"], "subsection_headings": ["1. Overview", "2. Nodes and Edges", "3. Time and Update Order", "4. Vehicles", "5. Consignments (Packages)", "6. Legal Actions Per Tick", "7. Edge Capacity, Queues, and Conflicts", "8. Traffic Signals", "9. Loading and Unloading", "10. Incidents and Road Closures", "11. Priorities and Service Levels", "12. Controller Objectives", "13. Rule Conflicts and Undefined Behavior", "1. Map Overview", "2. Edges", "3. Signal Settings", "4. Vehicles in the Morning Rush Scenario", "5. Consignments", "6. Incidents", "7. Scenario Horizon and Objective", "1. State Snapshot Format", "1.1 GLOBAL Section", "1.2 NODES Section", "1.3 EDGES Section", "1.4 VEHICLES Section", "1.5 CONSIGNMENTS Section", "1.6 INCIDENTS_ACTIVE Section", "2. Worked Example A:Simple Departure", "3. Worked Example B:Signal at Central Intersection", "4. Worked Example C:Capacity Reduction Incident"], "context_snippets": [], "heading_number": "", "heading_kind": "outline_llm", "section_summary": "R1. The Arclight Freight Network (AFN) is a fictional urban road and logistics system used to simulate movement of vehicles and packages over discrete time steps."}}], "supports": [{"support_id": "2774c35e-1852-5ec3-b78f-6d0bcf5196ef", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "section": "User Questions", "excerpt": "At tick 6 (t mod 6 = 0, Phase A), E2 is green but E5 is not; V2 may enter N3 at tick 6, while V3 must wait until Phase B (ticks 2-3 modulo 6), ie, tick 8 or 9, to enter.

